{
  "story": "A key is hashed into an array index. Collisions are handled by probing the next available slot to store the value safely.",
  "aha": {
    "stateId": "probe",
    "observation": "When slot 1 is occupied, linear probing checks the very next index until an empty slot is found."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Hash", "Index", "Collision", "Probe", "Insert"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Hash Table Insertion",
        "regions": [
          {
            "id": "key",
            "label": "Key",
            "kind": "cell",
            "values": ["cat"]
          },
          {
            "id": "hash",
            "label": "Hash Function",
            "kind": "cell",
            "values": ["hash('cat') = 1"]
          },
          {
            "id": "slot0",
            "label": "Index 0",
            "kind": "cell",
            "values": ["empty"]
          },
          {
            "id": "slot1",
            "label": "Index 1",
            "kind": "cell",
            "values": ["dog"]
          },
          {
            "id": "slot2",
            "label": "Index 2",
            "kind": "cell",
            "values": ["empty"]
          }
        ],
        "states": [
          {
            "id": "hash",
            "label": "Hash",
            "short": "Hash",
            "sentence": "The key 'cat' is passed into a hash function.",
            "why": "Computes an integer from string data.",
            "active": ["key"],
            "calloutRegion": "key",
            "readouts": [
              {
                "id": "r1",
                "label": "Input Key",
                "value": "cat"
              }
            ]
          },
          {
            "id": "index",
            "label": "Index",
            "short": "Index",
            "sentence": "The hash function returns target index 1.",
            "why": "Maps infinite keys to finite table slots.",
            "active": ["hash"],
            "calloutRegion": "hash",
            "readouts": [
              {
                "id": "r1",
                "label": "Hash Value",
                "value": "1"
              }
            ]
          },
          {
            "id": "collision",
            "label": "Collision",
            "short": "Collision",
            "sentence": "Index 1 is already occupied by 'dog'.",
            "why": "Two different keys generated the same index.",
            "active": ["slot1"],
            "calloutRegion": "slot1",
            "readouts": [
              {
                "id": "r1",
                "label": "Slot 1 Status",
                "value": "Occupied"
              }
            ]
          },
          {
            "id": "probe",
            "label": "Probe",
            "short": "Probe",
            "sentence": "Linear probing checks the next slot, index 2.",
            "why": "Finds the next available home without losing data.",
            "active": ["slot2"],
            "calloutRegion": "slot2",
            "readouts": [
              {
                "id": "r1",
                "label": "Probe Target",
                "value": "Index 2"
              }
            ]
          },
          {
            "id": "insert",
            "label": "Insert",
            "short": "Insert",
            "sentence": "Stored 'cat' successfully in index 2.",
            "why": "Table remains consistent and queryable.",
            "active": ["slot2", "key"],
            "calloutRegion": "slot2",
            "readouts": [
              {
                "id": "r1",
                "label": "Final Location",
                "value": "Index 2"
              }
            ]
          }
        ]
      }
    ]
  }
}
